index b074df31..b3e44cbe 100644
--- a/examples/logue/logue-core.birnam
+++ b/examples/logue/logue-core.birnam
@@ -143,8 +143,7 @@ let isPlayerAt := [:x :y |
 // ===========================================================================

 let monsterAt := [:x :y |
-  let hits := [[monsters value] select: [:m | [[[m at: #x] = x] & [[m at: #y] = y]]]];
-  [[[hits size] > 0] ifTrue: [| [hits at: 0]] ifFalse: [| nil]]];
+  [[monsters value] detect: [:m | [[[m at: #x] = x] & [[m at: #y] = y]]]]];

 let occupied := [:x :y | [[[monsterAt value: x value: y] isNil] not]];

@@ -349,8 +348,7 @@ let equipArmor := [:name :def |
 // ===========================================================================

 let itemAt := [:x :y |
-  let hits := [[items value] select: [:it | [[[it at: #x] = x] & [[it at: #y] = y]]]];
-  [[[hits size] > 0] ifTrue: [| [hits at: 0]] ifFalse: [| nil]]];
+  [[items value] detect: [:it | [[[it at: #x] = x] & [[it at: #y] = y]]]]];

 let removeItemAt := [:x :y |
   [items set: [[items value] select: [:it | [[[[it at: #x] = x] & [[it at: #y] = y]] not]]]]];
diff --git a/modules/stackless-control.birnam b/modules/stackless-control.birnam
index ed68cadb..25a50edf 100644
--- a/modules/stackless-control.birnam
+++ b/modules/stackless-control.birnam
@@ -187,6 +187,31 @@
       ifTrue: [| found]
       ifFalse: [| [[body value: each] ifTrue: [| each] ifFalse: [| nil]]]]]]]];

+// Keep the fold fallback for collections that only implement inject:into:.
+// Indexable families can finish without traversing the suffix. A matching nil
+// still means "not found", as in the fold; ordinary Error results remain values.
+// Size, elements, predicates and recursive steps are all ordinary live sends.
+[Reflect defineMethod: #detect: on: Vector as: [:self :body |
+  [self stacklessDetect: body from: 0]]];
+[Reflect defineMethod: #detect: on: Range as: [:self :body |
+  [self stacklessDetect: body from: 0]]];
+[Reflect defineMethod: #detect: on: String as: [:self :body |
+  [self stacklessDetect: body from: 0]]];
+[Reflect defineMethod: #detect: on: MapVt as: [:self :body |
+  [[self values] detect: body]]];
+
+[Reflect defineMethod: #stacklessDetect:from: on: Collection as: [:self :body :index |
+  [[index >= [self size]]
+    ifTrue: [| nil]
+    ifFalse: [|
+      let each := [self at: index];
+      [[body value: each]
+        ifTrue: [|
+          [[each notNil]
+            ifTrue: [| each]
+            ifFalse: [| [self stacklessDetect: body from: [index + 1]]]]]
+        ifFalse: [| [self stacklessDetect: body from: [index + 1]]]]]]]];
+
 [Reflect defineMethod: #detect:ifNone: on: Collection as: [:self :body :none |
   let found := [self detect: body];
   [[found notNil] ifTrue: [| found] ifFalse: [| [none value]]]]];
